import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface WasteIn {
  /** Default: today */
  recorded_on?: string | null;
  category: "Infectious" | "Sharps" | "Pathological" | "Pharmaceutical" | "Chemical" | "Radioactive" | "NonRisk";
  /** The ward (GET /beds/matrix?include_beds=false) */
  ward_id?: number | null;
  /** The department (GET /admin/departments) */
  department_id?: number | null;
  location?: string | null;
  bags?: number | null;
  weight_kg: number;
  /** The waste contractor who took it, when it took it at the collection (GET /finance/vendors); later: POST /infection/waste/handover */
  vendor_id?: number | null;
  manifest_number?: string | null;
  disposal?: "Incineration" | "Autoclave" | "Encapsulation" | "Landfill" | "Recycling" | "Other" | null;
  note?: string | null;
}

