/** Record hospital waste — POST /api/v1/infection/waste (who may call: holders of infection.waste.record). */
export function recordWaste(body: WasteIn): Promise<WasteRecordOut> {
  return api<WasteRecordOut>("POST", `/infection/waste`, body, { idempotent: true });
}

/** The waste log — GET /api/v1/infection/waste (who may call: holders of infection.waste.record or infection.control.manage or infection.statistics.view). */
export function listWaste(query?: { date_from?: string | null; date_to?: string | null; category?: "Infectious" | "Sharps" | "Pathological" | "Pharmaceutical" | "Chemical" | "Radioactive" | "NonRisk" | null; limit?: number; awaiting_handover?: boolean }): Promise<WasteLogOut> {
  return api<WasteLogOut>("GET", withQuery(`/infection/waste`, query), undefined);
}

/** Vendors — GET /api/v1/finance/vendors (who may call: any logged-in user). */
export function vendors(query?: { vendor_type?: "PharmacySupplier" | "ReagentSupplier" | "EquipmentSupplier" | "UtilityProvider" | "Contractor" | "Other" | null }): Promise<VendorOut[]> {
  return api<VendorOut[]>("GET", withQuery(`/finance/vendors`, query), undefined);
}

/** Hand collected waste over to the contractor — POST /api/v1/infection/waste/handover (who may call: holders of infection.waste.record). */
export function handOverWaste(body: WasteHandoverIn): Promise<WasteHandoverOut> {
  return api<WasteHandoverOut>("POST", `/infection/waste/handover`, body, { idempotent: true });
}

/** Departments — GET /api/v1/admin/departments (who may call: any logged-in user). */
export function departments(): Promise<DepartmentOut[]> {
  return api<DepartmentOut[]>("GET", `/admin/departments`, undefined);
}

/** Live bed matrix (counts per ward + optional bed list) — GET /api/v1/beds/matrix (who may call: holders of ipd.bed.view or cssd.operate or infection.control.manage or complaint.manage or incident.view or facility.drill.manage or roster.manage.all or facility.equipment.manage or pharmacy.storage.record). */
export function bedMatrix(query?: { include_beds?: boolean }): Promise<BedMatrixOut> {
  return api<BedMatrixOut>("GET", withQuery(`/beds/matrix`, query), undefined);
}
